"""Illustrations grounded in Chanel slides 4–7, 12–13 and the Boscha report."""
def chanel_scene():
 return '''<section class="section logistics-experience" id="reseau-chanel"><p class="eyebrow">DE LA PRÉSENTATION AU RÉSEAU</p><h2>Les bons stocks.<br>Au bon endroit.</h2><p>Explorez les deux pistes de notre présentation : rapprocher le stock des marchés, puis découpler les flux vers les Amériques.</p><div class="segmented" role="group" aria-label="Organisation logistique Chanel"><button data-logistics="before" aria-pressed="true">01 · Avant</button><button data-logistics="warehouses" aria-pressed="false">02 · Warehouses · C</button><button data-logistics="hubs" aria-pressed="false">03 · Hubs · B</button></div><div class="map-frame" data-domain-scene="chanel"><svg id="logistics-map" viewBox="0 0 800 533" role="img" aria-labelledby="map-title map-desc"><title id="map-title">Organisation initiale de la distribution</title><desc id="map-desc">La production et l’entrepôt en France alimentent les boutiques internationales. Les options permettent d’explorer les propositions de warehouses régionaux et de hubs américains.</desc><defs><marker id="cargo-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0 0L10 5L0 10Z" fill="#963854"/></marker><marker id="info-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0 0L10 5L0 10Z" fill="#167a72"/></marker></defs><image href="assets/chanel-world-map.webp" width="800" height="533" opacity=".45"/><g id="logistics-routes"></g><g id="logistics-buildings"></g><g id="logistics-parcels" aria-hidden="true"></g></svg><span class="map-badge">ÉTUDE ACADÉMIQUE · SCÉNARIO PROPOSÉ</span></div><div class="map-legend"><span><i class="cargo-key"></i>Produits</span><span><i class="info-key"></i>Informations / besoins</span><button class="diagram-motion" aria-pressed="true">Mettre les flux en pause</button></div><div class="logistics-story" aria-live="polite"><h3 id="logistics-title">Un stock dispersé dans les boutiques</h3><p id="logistics-copy">Le diagnostic présenté pour les produits C décrit une usine et un entrepôt en France, une distribution mondiale et des stocks importants en magasins.</p><div id="logistics-facts"></div></div><p class="source-note">Source : présentation Chanel, diapositives 4–7 et 12–13. Fond de carte repris du livrable. Les positions des warehouses C sont schématiques ; seuls les hubs B sont nommés dans le texte. Animation explicative, sans débit ni délai simulé. Les pourcentages B représentent la répartition proposée du volume de la zone Amériques.</p></section>'''

def boscha_scene():
 return '''<section class="section workshop-experience" id="atelier-boscha"><p class="eyebrow">BOSCHA / DANS L’ATELIER</p><h2>Deux gammes.<br>Une ressource partagée.</h2><p>Le centre CU22 intervient dans l’usinage des boîtiers et du SFPACK. Une file devant cette ressource peut retarder les opérations situées en aval.</p><div class="segmented" role="group" aria-label="Lecture de l’atelier Boscha"><button data-workshop="queue" aria-pressed="true">Voir le goulot CU22</button><button data-workshop="flows" aria-pressed="false">Suivre les pièces</button><button data-workshop="layout" aria-pressed="false">Voir l’implantation étudiée</button></div><div class="workshop-stage" data-domain-scene="boscha"><svg id="workshop-svg" viewBox="0 0 1000 520" role="img" aria-labelledby="workshop-title"><title id="workshop-title">Schéma de principe de deux flux partageant le centre d’usinage CU22</title><defs><pattern id="floor-grid" width="50" height="30" patternUnits="userSpaceOnUse"><path d="M50 0H0V30" stroke="#584c37" stroke-width=".5" fill="none"/></pattern></defs><rect x="20" y="30" width="960" height="460" rx="18" fill="#252b2c"/><rect x="20" y="30" width="960" height="460" rx="18" fill="url(#floor-grid)"/><path d="M100 170H385Q440 170 440 245H700Q760 245 760 160H890M100 365H385Q440 365 440 245M700 245Q760 245 760 365H890" class="workshop-conveyor"/><g id="workshop-machines"></g><g id="workshop-queue"></g><g id="workshop-parts" aria-hidden="true"></g></svg><img id="workshop-layout" src="assets/implantation-boscha.webp" alt="Plan d’implantation proposé dans la soutenance Boscha" width="1200" height="650" loading="lazy" hidden></div><div class="map-legend"><span>Pièces → Usinage partagé → Opérations en aval</span><button class="diagram-motion" aria-pressed="true">Mettre les flux en pause</button></div><p id="workshop-insight" class="flow-description" aria-live="polite">Le CU22 est identifié comme poste critique dans le rapport. Les pièces en attente illustrent ce mécanisme ; leur nombre n’est pas une mesure de l’étude.</p><p class="source-note">Schéma explicatif issu du rapport Boscha : boîtiers, SFPACK et centre CU22. Les étapes sont simplifiées, sans représenter une gamme complète ni un débit réel. L’onglet implantation affiche le véritable plan du livrable.</p></section>'''
